def _canonical_bytes(value: Mapping[str, Any]) -> bytes:
    try:
        return json.dumps(
            dict(value),
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise BehaviorHandoffError(
            "BEHAVIOR_HANDOFF_NOT_CANONICAL_JSON",
            "The handoff input is not deterministic JSON.",
        ) from exc


