  title: string;
  keywords: readonly string[];
  answer: string;
  href: string;
};

export const businessGuide: readonly BusinessGuideEntry[] = [
  {
    id: "overview",
    title: "Why Evidence Lane exists — end to end",
    keywords: ["business problem", "business language", "explain the whole", "whole project", "project continuity", "why evidence lane", "whole plugin", "overview", "end to end"],
    answer: "Evidence Lane is a governed memory and evidence system for long-running AI work. It addresses a specific operating problem: a new task, model, or host can otherwise force the user to re-explain the project while the AI reconstructs a plausible but unverifiable state. Evidence Lane keeps the exact accepted project version, source identities, visible user and AI lineage, unfinished work, later corrections, and the next human decision in an inspectable package.\n\nThe lifecycle is deliberate. Source Intake classifies authorized material into 18 lanes for distinct source types. Each lane preserves the structure needed for code, documents, data, images, research, plans, existing SQLite brains, or chat lineage. Build or Refresh can then create a sealed candidate with SQLite facts, search indexes, MMD and DOT topology, manifests, hashes, tests, and receipts. That candidate can be built, installed, or deployed and still remains outside accepted truth. A six-way HIL decision is the human gate, and only exact APPROVE may authorize the separate Fuse operation that moves the accepted pointer.\n\nThe current 3.0.0 pre-HIL source packages 17 governed skills and one package-local native MCP server with exactly 87 actions: 27 read-only and 60 write-capable. Accepted Project Truth remains at PV12/generation 12 until a fresh HIL. Installed testing, branch-recovery, and main-release identities remain separate measured facts. This release governs only a positively proven Codex layer; the public website documents it and never becomes lifecycle authority.\n\nWhat is proven is the mechanism: source boundaries, exact identities, retrieval, graph reconciliation, candidate isolation, negative cases, and human-controlled promotion.

Preview success, CI success, installation, or continued conversation is never HIL approval.",
    href: "/proof",
  },
] as const;

function normalized(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9.]+/g, " ").trim();
}

export function businessGuideFor(question: string) {
  const query = normalized(question);
  if (/\b(?:explain|describe|summarize)\b.*\b(?:whole|entire|end to end)\b/.test(query)
    || /\bwhole (?:evidence lane )?(?:project|plugin|product)\b/.test(query)) {
    return businessGuide.find((entry) => entry.id === "overview") ?? null;
  }
  const queryWords = new Set(query.split(/\s+/).filter((word) => word.length > 2));
  let best: { entry: BusinessGuideEntry; score: number } | null = null;
  for (const entry of businessGuide) {
    const score = entry.keywords.reduce((total, keyword) => {
      const phrase = normalized(keyword);
      if (query.includes(phrase)) return total + 5;
      const overlaps = phrase.split(/\s+/).filter((word) => queryWords.has(word)).length;
      return total + overlaps;
    }, 0);
    if (score > (best?.score ?? 0)) best = { entry, score };
  }
  return best && best.score >= 2 ? best.entry : null;
}
