        raise PackageBoundaryError(
            f"Expected {EXPECTED_SKILL_COUNT} skills, found {len(skill_files)}."
        )
    rows = []
    for path in skill_files:
        relative = path.relative_to(plugin_root).as_posix()
        rows.append(
            {
