    @staticmethod
    def _expiry_is_live(value: str) -> bool:
        if value == "NO_EXPIRY":
            return True
        try:
            parsed = datetime.fromisoformat(value)
        except ValueError:
            return False
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=UTC)
        return parsed > datetime.now(UTC)

