def _sdk_forbidden_public_paths(
    value: object,
    *,
    path: tuple[str, ...] = (),
    depth: int = 0,
) -> list[str]:
    """Find authority blobs that may be stored but never returned publicly."""

    if depth > 8:
        return []
    if isinstance(value, Mapping):
        found: list[str] = []
        for raw_key, nested in list(value.items())[:128]:
            key = str(raw_key)
            exact_path = (*path, key)
            if key.lower() in _SDK_FORBIDDEN_PUBLIC_KEYS:
                found.append(".".join(exact_path))
            else:
                found.extend(
                    _sdk_forbidden_public_paths(
                        nested,
                        path=exact_path,
                        depth=depth + 1,
                    )
                )
            if len(found) >= 32:
                return found[:32]
        return found
    if isinstance(value, list):
        found = []
        for index, nested in enumerate(value[:50]):
            found.extend(
                _sdk_forbidden_public_paths(
                    nested,
                    path=(*path, str(index)),
                    depth=depth + 1,
                )
            )
            if len(found) >= 32:
                return found[:32]
        return found
    return []

