    text = " ".join(
        (
            str(row.get("task_id") or ""),
            str(row.get("step") or ""),
        )
    ).upper()
    return bool(
        role == "PHYSICALLY_FINAL_HIL"
        or _row_pv_ordinals(row)
        or (
            "HIL" in text
            and any(
                marker in text
                for marker in ("CANDIDATE", "FUSE", "POINTER", "REFRESH", "RELEASE")
            )
        )
    )


