            "SUCCESSOR_ADDENDUM_IMMUTABILITY_CONFLICT",
            "The exact release addendum already exists with different bytes.",
            status="BLOCKED",
            path=str(path),
        )
        return "REUSED"
    atomic_write_bytes(path, content)
    return "CREATED"

